const PAGE_ID = '1344374618757432';
const TOK = '__FB_PAGE_TOKEN__';
const G = 'https://graph.facebook.com/v26.0';
const LOCAL = 'http://host.docker.internal:5678/webhook/chatdesk-fb';
const st = $getWorkflowStaticData('global');
const now = Date.now();
if (!st.lastCheck) st.lastCheck = now - 15*60*1000;
if (!Array.isArray(st.seen)) st.seen = [];
const seen = new Set(st.seen);
const since = st.lastCheck;
const injected = [];
const th = await this.helpers.httpRequest({method:'GET',
  url: G + '/me/conversations?fields=id,updated_time,message_count&limit=20&access_token=' + TOK,
  json:true, timeout:30000});
for (const t of (th.data || [])) {
  let m;
  try {
    m = await this.helpers.httpRequest({method:'GET',
      url: G + '/' + t.id + '/messages?fields=id,message,from,created_time&limit=15&access_token=' + TOK,
      json:true, timeout:30000});
  } catch(e) { continue; }
  const msgs = (m.data || []).slice().sort((a,b) => new Date(a.created_time) - new Date(b.created_time));
  for (const g of msgs) {
    const ts = new Date(g.created_time).getTime();
    const mid = g.id || '';
    const fromId = (g.from && g.from.id) || '';
    const text = (g.message || '').toString().trim();
    if (!mid || !text || fromId === PAGE_ID) continue;
    if (ts <= since || seen.has(mid)) continue;
    const body = {object:'page', entry:[{id: PAGE_ID, time: Math.floor(ts/1000),
      messaging:[{sender:{id:fromId}, recipient:{id:PAGE_ID}, timestamp: ts,
        message:{mid: mid, text: text}}]}]};
    await this.helpers.httpRequest({method:'POST', url: LOCAL, json:true, timeout:30000, body});
    seen.add(mid); injected.push(mid);
  }
}
st.seen = Array.from(seen).slice(-300);
st.lastCheck = now;
return [{json:{ok:true, injected: injected.length, mids: injected}}];
